#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k;
    cin >> n >> m >> k;
    // g[i][j]: the minute cell (i, j) turns black; a square is done at the max over its cells.
    vector<int> g(n * m);
    for (int t = 1; t <= n * m; t++) {
        int r, c;
        cin >> r >> c;
        g[(r - 1) * m + (c - 1)] = t;
    }
    int w = m - k + 1;
    vector<int> rows(n * w), q(max(n, m));
    // Sliding-window max of width k along each row (monotone queue q[head..tail)).
    for (int i = 0; i < n; i++) {
        const int* row = &g[i * m];
        int head = 0, tail = 0;
        for (int j = 0; j < m; j++) {
            while (tail > head && row[q[tail - 1]] <= row[j]) tail--;
            q[tail++] = j;
            if (q[head] <= j - k) head++;
            if (j >= k - 1) rows[i * w + j - k + 1] = row[q[head]];
        }
    }
    // Then along each column of the row maxima; the smallest square maximum is the answer.
    int answer = n * m;
    for (int j = 0; j < w; j++) {
        int head = 0, tail = 0;
        for (int i = 0; i < n; i++) {
            while (tail > head && rows[q[tail - 1] * w + j] <= rows[i * w + j]) tail--;
            q[tail++] = i;
            if (q[head] <= i - k) head++;
            if (i >= k - 1) answer = min(answer, rows[q[head] * w + j]);
        }
    }
    cout << answer << "\n";
}

import java.io.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    private static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt(), k = nextInt();
        // g[i][j]: the minute cell (i, j) turns black; a square is done at the max over its cells.
        int[] g = new int[n * m];
        for (int t = 1; t <= n * m; t++) {
            int r = nextInt(), c = nextInt();
            g[(r - 1) * m + (c - 1)] = t;
        }
        int w = m - k + 1;
        int[] rows = new int[n * w], q = new int[Math.max(n, m)];
        // Sliding-window max of width k along each row (monotone queue q[head..tail)).
        for (int i = 0; i < n; i++) {
            int base = i * m, head = 0, tail = 0;
            for (int j = 0; j < m; j++) {
                while (tail > head && g[base + q[tail - 1]] <= g[base + j]) tail--;
                q[tail++] = j;
                if (q[head] <= j - k) head++;
                if (j >= k - 1) rows[i * w + j - k + 1] = g[base + q[head]];
            }
        }
        // Then along each column of the row maxima; the smallest square maximum is the answer.
        int answer = n * m;
        for (int j = 0; j < w; j++) {
            int head = 0, tail = 0;
            for (int i = 0; i < n; i++) {
                while (tail > head && rows[q[tail - 1] * w + j] <= rows[i * w + j]) tail--;
                q[tail++] = i;
                if (q[head] <= i - k) head++;
                if (i >= k - 1) answer = Math.min(answer, rows[q[head] * w + j]);
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m, k := nextInt(), nextInt(), nextInt()
	// g[i*m+j]: the minute cell (i, j) turns black; a square is done at the max over its cells.
	g := make([]int32, n*m)
	for t := 1; t <= n*m; t++ {
		r, c := nextInt(), nextInt()
		g[(r-1)*m+c-1] = int32(t)
	}
	w := m - k + 1
	rows, q := make([]int32, n*w), make([]int, max(n, m))
	// Sliding-window max of width k along each row (monotone queue q[head:tail]).
	for i := 0; i < n; i++ {
		row := g[i*m : (i+1)*m]
		head, tail := 0, 0
		for j := 0; j < m; j++ {
			for tail > head && row[q[tail-1]] <= row[j] {
				tail--
			}
			q[tail] = j
			tail++
			if q[head] <= j-k {
				head++
			}
			if j >= k-1 {
				rows[i*w+j-k+1] = row[q[head]]
			}
		}
	}
	// Then along each column of the row maxima; the smallest square maximum is the answer.
	answer := int32(n * m)
	for j := 0; j < w; j++ {
		head, tail := 0, 0
		for i := 0; i < n; i++ {
			for tail > head && rows[q[tail-1]*w+j] <= rows[i*w+j] {
				tail--
			}
			q[tail] = i
			tail++
			if q[head] <= i-k {
				head++
			}
			if i >= k-1 {
				answer = min(answer, rows[q[head]*w+j])
			}
		}
	}
	os.Stdout.WriteString(strconv.Itoa(int(answer)) + "\n")
}
